//! Recursive descent and operator-precedence parser for XCL source code.
//!
//! # Overview
//!
//! The parser takes the linear sequence of [`TokenWithText`](crate::lexer::TokenWithText)
//! generated by [`lex`](crate::lexer::lex) and constructs an Abstract Syntax Tree
//! represented by a [`Vec<AstNode>`](crate::ast::AstNode).
//!
//! # Parsing Strategy
//!
//! * **Statements**: Parsed using recursive descent with lookahead. Handled constructs include
//!   variable assignments (`$x = 42`), loop statements (`for`, `while`), branch statements (`if`/`else`),
//!   function definitions (`name($args) { ... }`), custom type definitions (`Point = { ... }`),
//!   trait implementations (`Human is Walk { ... }`), and `defer` cleanup blocks.
//! * **Expressions**: Parsed using Pratt / precedence climbing to correctly resolve operator
//!   precedence and associativity for arithmetic, comparisons, logical operations, and pipeline (`|>`) chaining.
//!
//! # Examples
//!
//! Parsing source code into an AST:
//!
//! ```
//! use xcl_vm::compiler::lexer::lex;
//! use xcl_vm::compiler::parser::parse;
//! use xcl_vm::compiler::ast::AstNode;
//!
//! let source = "$total = 100 + 50;";
//! let tokens = lex(source, "main.xcl");
//! let ast = parse(&tokens, source);
//!
//! assert_eq!(ast.len(), 1);
//! match &ast[0] {
//!     AstNode::Assign { name, .. } => assert_eq!(name, "total"),
//!     _ => panic!("Expected assignment"),
//! }
//! ```

#[cfg(not(feature = "std"))]
use alloc::boxed::Box;
#[cfg(not(feature = "std"))]
use alloc::format;
#[cfg(not(feature = "std"))]
use alloc::string::String;
#[cfg(not(feature = "std"))]
use alloc::string::ToString;
#[cfg(not(feature = "std"))]
use alloc::vec;
#[cfg(not(feature = "std"))]
use alloc::vec::Vec;

use crate::compiler::ast::{
    AstNode, BinaryOperator, CallArg, Param, PipelineStage, SpecialVarKind, SumVariant, TypeField,
    TypeKind, UnaryOperator,
};
use crate::compiler::lexer::{Token, TokenWithText, extract_string};
use crate::compiler::span::Span;

struct Parser<'a> {
    tokens: &'a [TokenWithText],
    pos: usize,
    source: &'a str,
    /// Tracks nesting depth of pipeline stages; when > 0, lambda bodies should not consume `|>`.
    pipeline_depth: usize,
}

impl<'a> Parser<'a> {
    fn new(tokens: &'a [TokenWithText], source: &'a str) -> Self {
        Self {
            tokens,
            pos: 0,
            source,
            pipeline_depth: 0,
        }
    }

    #[inline]
    fn current(&self) -> Option<&TokenWithText> {
        self.tokens.get(self.pos)
    }
    #[inline]
    fn at_eof(&self) -> bool {
        self.pos >= self.tokens.len()
    }

    fn span(&self) -> Span {
        self.current()
            .map(|t| t.span.clone())
            .unwrap_or_else(Span::empty)
    }

    fn consume(&mut self) -> TokenWithText {
        let t = self.current().cloned().unwrap_or_else(|| TokenWithText {
            token: Token::RParen,
            text: String::new(),
            span: Span::empty(),
            byte_offset: 0,
        });
        self.pos += 1;
        t
    }

    fn expect(&mut self, want: Token) {
        let t = self.consume();
        if t.token != want {
            panic!(
                "XCL {}:{}: expected {:?}, got {:?} ({})",
                t.span.file, t.span.line, want, t.token, t.text
            );
        }
    }

    #[inline]
    fn at(&self, tok: Token) -> bool {
        self.current().map(|t| t.token == tok).unwrap_or(false)
    }

    fn program(&mut self) -> Vec<AstNode> {
        let mut out = Vec::new();
        while !self.at_eof() {
            if self.at(Token::Semi) {
                self.consume();
                continue;
            }
            // Skip stray RBrace at program level — can happen if a block-lambda
            // consumed a closing brace that belonged to an outer scope.
            if self.at(Token::RBrace) {
                self.consume();
                continue;
            }
            out.push(self.statement());
        }
        out
    }

    fn statement(&mut self) -> AstNode {
        match self.current().map(|t| &t.token) {
            Some(Token::Return) => self.ret(),
            Some(Token::Break) => {
                let s = self.span();
                self.consume();
                AstNode::Break { span: s }
            }
            Some(Token::Continue) => {
                let s = self.span();
                self.consume();
                AstNode::Continue { span: s }
            }
            Some(Token::If) => self.if_expr(),
            Some(Token::For) => self.for_expr(),
            Some(Token::While) => self.while_expr(),
            Some(Token::Ident) if self.lookahead_assign() => self.assign(),
            Some(Token::IdentPlain) if self.lookahead_fn_def() => self.fn_def(),
            // Type definition: `Name = { ... }` or `Name = | Variant1 { ... } | Variant2 { ... }`
            Some(Token::IdentPlain) if self.lookahead_type_def() => self.type_def(),
            // Impl block: `Name is Trait { ... }`
            Some(Token::IdentPlain) if self.lookahead_impl_def() => self.impl_def(),
            // `defer { ... }` — keyword-like syntax for deferred closures
            Some(Token::IdentPlain) if self.lookahead_defer() => self.defer_expr(),
            Some(Token::SpecialVar) | Some(Token::UnsupportedSpecialVar)
                if self.lookahead_assign() =>
            {
                panic!(
                    "XCL {}:{}: special variable `{}` is read-only",
                    self.span().file,
                    self.span().line,
                    self.current().map(|t| t.text.as_str()).unwrap_or("")
                )
            }
            _ => self.expr_stmt(),
        }
    }

    #[inline]
    fn lookahead_defer(&self) -> bool {
        // `defer` followed by `{`
        if self.current().map(|t| t.text != "defer").unwrap_or(true) {
            return false;
        }
        matches!(
            self.tokens.get(self.pos + 1).map(|t| &t.token),
            Some(Token::LBrace)
        )
    }

    fn defer_expr(&mut self) -> AstNode {
        let span = self.span();
        self.consume(); // consume "defer"
        // Parse the block { ... }
        let statements = self.block();
        // Wrap in: defer( Lambda { params: [], body: Block { statements } } )
        let lambda = AstNode::Lambda {
            span: span.clone(),
            params: vec![],
            body: Box::new(AstNode::Block {
                span: span.clone(),
                statements,
            }),
        };
        AstNode::Call {
            span: span.clone(),
            callee: Box::new(AstNode::Ident {
                span,
                name: "defer".to_string(),
            }),
            args: vec![CallArg {
                value: lambda,
                name: None,
            }],
        }
    }

    #[inline]
    fn lookahead_type_def(&self) -> bool {
        // Name = { or Name = | ... or Name = Variant | ... or Name = Variant { ... } | ...
        if !matches!(
            self.tokens.get(self.pos + 1).map(|t| &t.token),
            Some(Token::Assign)
        ) {
            return false;
        }
        match self.tokens.get(self.pos + 2).map(|t| &t.token) {
            Some(Token::LBrace) | Some(Token::Pipe) => true,
            // `Name = IdentPlain |` — enum-style without leading pipe
            // `Name = IdentPlain {` — variant with fields
            Some(Token::IdentPlain) => {
                matches!(
                    self.tokens.get(self.pos + 3).map(|t| &t.token),
                    Some(Token::Pipe) | Some(Token::LBrace)
                )
            }
            _ => false,
        }
    }

    #[inline]
    fn lookahead_impl_def(&self) -> bool {
        // Name is Trait {
        if !matches!(
            self.tokens.get(self.pos + 1).map(|t| &t.token),
            Some(Token::Is)
        ) {
            return false;
        }
        // Check for: Name is IdentPlain {
        if !matches!(
            self.tokens.get(self.pos + 2).map(|t| &t.token),
            Some(Token::IdentPlain)
        ) {
            return false;
        }
        matches!(
            self.tokens.get(self.pos + 3).map(|t| &t.token),
            Some(Token::LBrace)
        )
    }

    fn type_def(&mut self) -> AstNode {
        let span = self.span();
        let name = self.consume().text; // IdentPlain
        self.expect(Token::Assign);

        if self.at(Token::Pipe) || self.at(Token::IdentPlain) {
            // Sum type: `Name = | Variant1 | Variant2` or `Name = Variant1 | Variant2`
            let mut variants = Vec::new();
            // If starts with `|`, consume it first (old syntax)
            if self.at(Token::Pipe) {
                self.consume();
            }
            while self.at(Token::IdentPlain) {
                // Check if this IdentPlain is followed by `=` — that means it's a new
                // assignment statement, not a variant name. Stop parsing variants.
                if matches!(
                    self.tokens.get(self.pos + 1).map(|t| &t.token),
                    Some(Token::Assign)
                ) {
                    break;
                }
                let vname = self.consume().text;
                let mut fields = Vec::new();
                if self.at(Token::LBrace) {
                    self.consume(); // {
                    while !self.at(Token::RBrace) && !self.at(Token::Pipe) && !self.at_eof() {
                        if self.at(Token::Semi) {
                            self.consume();
                            continue;
                        }
                        let fname = self.consume().text;
                        self.expect(Token::Colon);
                        let fty = self.parse_type();
                        fields.push(TypeField {
                            name: fname,
                            ty: fty,
                            mutable: false,
                        });
                        if self.at(Token::Semi) {
                            self.consume();
                        }
                    }
                    self.expect(Token::RBrace);
                }
                variants.push(SumVariant {
                    name: vname,
                    fields,
                });
                if self.at(Token::Pipe) {
                    self.consume();
                }
            }
            AstNode::TypeDef {
                span,
                name,
                kind: TypeKind::Sum { variants },
                body: Vec::new(),
            }
        } else {
            // Record or Trait: `Name = { ... }`
            self.expect(Token::LBrace);
            let mut body = Vec::new();
            while !self.at(Token::RBrace) && !self.at_eof() {
                if self.at(Token::Semi) || self.at(Token::Comma) {
                    self.consume();
                    continue;
                }
                // Check if it's a method definition
                if self.at(Token::IdentPlain) && self.lookahead_fn_def() {
                    body.push(self.fn_def());
                } else {
                    // Field definition: `name: type` or `mut name: type`
                    let span = self.span();
                    let mut _mutable = false;
                    if self.at(Token::IdentPlain)
                        && self.current().map(|t| t.text == "mut").unwrap_or(false)
                    {
                        _mutable = true;
                        self.consume();
                    }
                    let fname = self.consume().text;
                    self.expect(Token::Colon);
                    let fty = self.parse_type();
                    // Store as a synthetic assign node for now; compiler will handle it
                    body.push(AstNode::Assign {
                        span,
                        name: format!("__field__{}__{}__", fname, fty),
                        value: Box::new(AstNode::Nil {
                            span: Span::empty(),
                        }),
                        type_annotation: None,
                    });
                    if self.at(Token::Semi) {
                        self.consume();
                    }
                }
            }
            self.expect(Token::RBrace);
            // Determine if trait (only methods) or record (has fields)
            let kind = if body
                .iter()
                .all(|n| matches!(n, AstNode::FunctionDef { .. }))
            {
                TypeKind::Trait
            } else {
                TypeKind::Record
            };
            AstNode::TypeDef {
                span,
                name,
                kind,
                body,
            }
        }
    }

    fn impl_def(&mut self) -> AstNode {
        let span = self.span();
        let type_name = self.consume().text; // IdentPlain
        self.expect(Token::Is);
        let trait_name = self.consume().text; // IdentPlain
        self.expect(Token::LBrace);
        let mut body = Vec::new();
        while !self.at(Token::RBrace) && !self.at_eof() {
            if self.at(Token::Semi) {
                self.consume();
                continue;
            }
            if self.at(Token::IdentPlain) && self.lookahead_fn_def() {
                body.push(self.fn_def());
            } else {
                // Skip unknown content
                self.consume();
            }
        }
        self.expect(Token::RBrace);
        AstNode::ImplDef {
            span,
            type_name,
            trait_name,
            body,
        }
    }

    #[inline]
    fn lookahead_dict_literal(&self) -> bool {
        // self.pos already points past the consumed `{`, so start here.
        // Find the first meaningful token. If it's followed by `:`, it's a dict literal.
        // Otherwise, it's a block-lambda.
        // `{ }` → empty block-lambda (returns nil)
        let mut i = self.pos;
        while i < self.tokens.len() {
            match self.tokens[i].token {
                Token::RBrace => return false, // empty `{ }` → block-lambda
                Token::Semi | Token::Comma => {
                    i += 1;
                    continue;
                }
                _ => {
                    // Found the first meaningful token — check if next is `:`
                    return matches!(self.tokens.get(i + 1).map(|t| &t.token), Some(Token::Colon));
                }
            }
        }
        false // reached EOF without `}` → block-lambda
    }

    #[inline]
    fn lookahead_assign(&self) -> bool {
        matches!(
            self.tokens.get(self.pos + 1).map(|t| &t.token),
            Some(Token::Assign)
                | Some(Token::AddAssign)
                | Some(Token::SubAssign)
                | Some(Token::MulAssign)
                | Some(Token::DivAssign)
                | Some(Token::BitOrAssign)
                | Some(Token::BitXorAssign)
                | Some(Token::PowAssign)
                | Some(Token::CoalesceAssign)
                | Some(Token::Colon)
        )
    }

    #[inline]
    fn lookahead_fn_def(&self) -> bool {
        // Must be: name( ... ) { or name( ... ) ->
        // We scan forward past the parens to check for a block or return type.
        if !matches!(
            self.tokens.get(self.pos + 1).map(|t| &t.token),
            Some(Token::LParen)
        ) {
            return false;
        }
        // Find the matching closing paren
        let mut depth = 1;
        let mut i = self.pos + 2;
        while i < self.tokens.len() && depth > 0 {
            match self.tokens[i].token {
                Token::LParen => depth += 1,
                Token::RParen => depth -= 1,
                _ => {}
            }
            i += 1;
        }
        if depth != 0 {
            return false;
        }
        // After the closing paren, expect { or ->
        matches!(
            self.tokens.get(i).map(|t| &t.token),
            Some(Token::LBrace) | Some(Token::RArrow)
        )
    }

    fn assign(&mut self) -> AstNode {
        let span = self.span();
        let name = self.consume().text.trim_start_matches('$').to_string();
        let type_annotation = if self.at(Token::Colon) {
            self.consume();
            Some(self.parse_type())
        } else {
            None
        };

        let compound = match self.current().map(|t| &t.token) {
            Some(Token::AddAssign) => Some(BinaryOperator::Add),
            Some(Token::SubAssign) => Some(BinaryOperator::Sub),
            Some(Token::MulAssign) => Some(BinaryOperator::Mul),
            Some(Token::DivAssign) => Some(BinaryOperator::Div),
            Some(Token::BitOrAssign) => Some(BinaryOperator::BitOr),
            Some(Token::BitXorAssign) => Some(BinaryOperator::BitXor),
            Some(Token::PowAssign) => Some(BinaryOperator::Pow),
            _ => None,
        };

        if let Some(op) = compound {
            self.consume();
            let value = Box::new(self.expr());
            return AstNode::Assign {
                span: span.clone(),
                name: name.clone(),
                value: Box::new(AstNode::BinaryOp {
                    span: span.clone(),
                    left: Box::new(AstNode::Ident {
                        span: span.clone(),
                        name,
                    }),
                    op,
                    right: value,
                }),
                type_annotation: None,
            };
        }

        if self.at(Token::CoalesceAssign) {
            self.consume();
            let value = Box::new(self.expr());
            return AstNode::Assign {
                span: span.clone(),
                name: name.clone(),
                value: Box::new(AstNode::BinaryOp {
                    span: span.clone(),
                    left: Box::new(AstNode::Ident {
                        span: span.clone(),
                        name,
                    }),
                    op: BinaryOperator::Coalesce,
                    right: value,
                }),
                type_annotation: None,
            };
        }

        self.expect(Token::Assign);
        let value = self.expr();
        let value = Box::new(self.bare_call_to_zero_arg(value));
        AstNode::Assign {
            span,
            name,
            value,
            type_annotation,
        }
    }

    /// If an expression is a bare FieldAccess on a $-variable or a domain function
    /// (starting with IdentPlain), convert it to a zero-arg Call.
    /// This enables scripting-style syntax: `$r.is_ok` and `cloudflare.config`.
    fn bare_call_to_zero_arg(&self, e: AstNode) -> AstNode {
        if let AstNode::FieldAccess { target, .. } = &e {
            if let AstNode::Ident { .. } = target.as_ref() {
                let span = self.span();
                return AstNode::Call {
                    span,
                    callee: Box::new(e),
                    args: vec![],
                };
            }
        }
        e
    }

    fn ret(&mut self) -> AstNode {
        let span = self.span();
        self.consume();
        let value = if !self.at_eof() && !self.at(Token::Semi) && !self.at(Token::RBrace) {
            // Don't parse if the next token starts a function definition (nested fn)
            // because expr() would try to parse it as a call
            let is_fn_def = self.at(Token::IdentPlain) && self.lookahead_fn_def();
            if is_fn_def {
                None
            } else {
                let e = self.expr();
                Some(Box::new(self.bare_call_to_zero_arg(e)))
            }
        } else {
            None
        };
        AstNode::Return { span, value }
    }

    fn if_expr(&mut self) -> AstNode {
        let span = self.span();
        self.consume();
        let condition = self.expr();
        // If the condition is a bare FieldAccess on a $-variable (like `$r.is_ok`),
        // convert it to a zero-arg method call so `.is_ok` works as a method.
        let condition = if let AstNode::FieldAccess { target, .. } = &condition {
            if let AstNode::Ident { .. } = target.as_ref() {
                AstNode::Call {
                    span: self.span(),
                    callee: Box::new(condition),
                    args: vec![],
                }
            } else {
                condition
            }
        } else {
            condition
        };
        let then_branch = self.block();
        let else_branch = self.else_branch();
        AstNode::If {
            span,
            condition: Box::new(condition),
            then_branch,
            else_branch,
        }
    }

    fn else_branch(&mut self) -> Option<Vec<AstNode>> {
        if self.at(Token::Else) {
            self.consume();
            if self.at(Token::If) {
                Some(vec![self.if_expr()])
            } else {
                Some(self.block())
            }
        } else {
            None
        }
    }

    fn for_expr(&mut self) -> AstNode {
        let span = self.span();
        self.consume();
        let variable = self.consume().text.trim_start_matches('$').to_string();
        self.expect(Token::In);
        let iterable = self.expr();
        let iterable = Box::new(self.bare_call_to_zero_arg(iterable));
        let body = self.block();
        AstNode::For {
            span,
            variable,
            iterable,
            body,
        }
    }

    fn while_expr(&mut self) -> AstNode {
        let span = self.span();
        self.consume();
        let condition = self.expr();
        let condition = Box::new(self.bare_call_to_zero_arg(condition));
        let body = self.block();
        AstNode::While {
            span,
            condition,
            body,
        }
    }

    /// Parse `name(params) { body }` — function definition without `fn` keyword.
    fn fn_def(&mut self) -> AstNode {
        let span = self.span();
        let name = self.consume().text.clone();
        self.expect(Token::LParen);
        let mut params = Vec::new();
        while !self.at(Token::RParen) && !self.at_eof() {
            params.push(self.param());
            if self.at(Token::Comma) {
                self.consume();
            }
        }
        self.expect(Token::RParen);
        let return_type = if self.at(Token::RArrow) {
            self.consume();
            Some(self.parse_type())
        } else {
            None
        };
        let body = self.block();
        AstNode::FunctionDef {
            span,
            name,
            params,
            return_type,
            body,
        }
    }

    fn param(&mut self) -> Param {
        let span = self.span();
        // Parameters must use $ prefix: $x, $name, etc.
        let t = self.consume();
        if !matches!(&t.token, Token::Ident) {
            panic!(
                "XCL {}:{}: parameter must use $ prefix, got '{}' (use ${} instead)",
                t.span.line, t.span.col, t.text, t.text
            );
        }
        let name = t.text.trim_start_matches('$').to_string();
        let type_annotation = if self.at(Token::Colon) {
            self.consume();
            Some(self.parse_type())
        } else {
            None
        };
        let default_value = if self.at(Token::Assign) {
            self.consume();
            Some(Box::new(self.expr()))
        } else {
            None
        };
        Param {
            name,
            type_annotation,
            default_value,
            span,
        }
    }

    fn parse_type(&mut self) -> String {
        let base = match self.current().map(|t| &t.token) {
            Some(Token::Str) => {
                self.consume();
                "str".to_string()
            }
            Some(Token::I8) => {
                self.consume();
                "i8".to_string()
            }
            Some(Token::I16) => {
                self.consume();
                "i16".to_string()
            }
            Some(Token::I32) => {
                self.consume();
                "i32".to_string()
            }
            Some(Token::I64) => {
                self.consume();
                "i64".to_string()
            }
            Some(Token::U8) => {
                self.consume();
                "u8".to_string()
            }
            Some(Token::U16) => {
                self.consume();
                "u16".to_string()
            }
            Some(Token::U32) => {
                self.consume();
                "u32".to_string()
            }
            Some(Token::U64) => {
                self.consume();
                "u64".to_string()
            }
            Some(Token::F32) => {
                self.consume();
                "f32".to_string()
            }
            Some(Token::F64) => {
                self.consume();
                "f64".to_string()
            }
            _ => self.consume().text.clone(),
        };
        if matches!(self.current().map(|t| &t.token), Some(Token::Lt)) {
            self.consume();
            let mut args = Vec::new();
            args.push(self.parse_type());
            while self.at(Token::Comma) {
                self.consume();
                args.push(self.parse_type());
            }
            self.expect(Token::Gt);
            return format!("{}<{}>", base, args.join(", "));
        }
        if base == "fn" && self.at(Token::LParen) {
            self.consume();
            let mut ps = Vec::new();
            while !self.at(Token::RParen) && !self.at_eof() {
                ps.push(self.parse_type());
                if self.at(Token::Comma) {
                    self.consume();
                }
            }
            self.expect(Token::RParen);
            if self.at(Token::RArrow) {
                self.consume();
                let r = self.parse_type();
                return format!("fn({}) -> {}", ps.join(", "), r);
            }
            return format!("fn({})", ps.join(", "));
        }
        base
    }

    fn block(&mut self) -> Vec<AstNode> {
        self.expect(Token::LBrace);
        let mut out = Vec::new();
        while !self.at(Token::RBrace) && !self.at_eof() {
            if self.at(Token::Semi) {
                self.consume();
                continue;
            }
            out.push(self.statement());
        }
        self.expect(Token::RBrace);
        out
    }

    fn expr_stmt(&mut self) -> AstNode {
        let e = self.expr();
        // $f $x call pattern: if expression is a plain $-ident (not FieldAccess)
        // and next token starts a positional arg, treat it as a call
        if let AstNode::Ident { .. } = &e
            && self.starts_positional_arg()
            && !self.has_newline_before_current()
        {
            let callee = e;
            let mut args = vec![self.call_arg()];
            while self.starts_positional_arg() && !self.has_newline_before_current() {
                args.push(self.call_arg());
            }
            if self.at(Token::Semi) {
                self.consume();
            }
            return AstNode::Call {
                span: self.span(),
                callee: Box::new(callee),
                args,
            };
        }
        // Bare IdentPlain or FieldAccess starting with IdentPlain at a statement
        // boundary is treated as a zero-argument call: `cloudflare.config` ==
        // `cloudflare.config ()`. Only applies to domain functions (IdentPlain),
        // NOT to $-variables (Ident) like `$m.key`.
        // The expression must have NO Call nodes inside (e.g., `cloud.config ().region`
        // is NOT a bare call because it contains a Call).
        // We check the token stream: walk backwards from current position to find
        // the first token of this expression and verify it's IdentPlain.
        fn contains_call(node: &AstNode) -> bool {
            match node {
                AstNode::Call { .. } => true,
                AstNode::FieldAccess { target, .. } => contains_call(target),
                AstNode::Index { target, index, .. } => {
                    contains_call(target) || contains_call(index)
                }
                AstNode::Ident { .. } => false,
                _ => true,
            }
        }
        // Walk backwards through tokens to find the first token of this expression.
        // Skip over Dot, OptionalDot, Ident, and IdentPlain tokens (part of FieldAccess chain).
        let first_token_is_ident_plain = if self.pos > 0 {
            let mut pos = self.pos - 1;
            while matches!(
                self.tokens[pos].token,
                Token::Dot | Token::OptionalDot | Token::Ident | Token::IdentPlain
            ) && pos > 0
            {
                pos -= 1;
            }
            matches!(self.tokens[pos].token, Token::IdentPlain)
        } else {
            false
        };
        // Bare domain function call: `cloudflare.config` at statement boundary
        if matches!(&e, AstNode::Ident { .. } | AstNode::FieldAccess { .. })
            && first_token_is_ident_plain
            && !contains_call(&e)
            && !self.starts_positional_arg()
            && (self.at_eof()
                || self.at(Token::Semi)
                || self.at(Token::RBrace)
                || self.has_newline_before_current())
        {
            if self.at(Token::Semi) {
                self.consume();
            }
            return AstNode::Call {
                span: self.span(),
                callee: Box::new(e),
                args: vec![],
            };
        }
        // Bare method call on $-variable: `$r.is_ok` at statement boundary
        // Walk backwards to check if the expression started with a $-variable (Token::Ident)
        let first_token_is_dollar_ident = if self.pos > 0 {
            let mut pos = self.pos - 1;
            while matches!(
                self.tokens[pos].token,
                Token::Dot | Token::OptionalDot | Token::Ident | Token::IdentPlain
            ) && pos > 0
            {
                pos -= 1;
            }
            matches!(self.tokens[pos].token, Token::Ident)
        } else {
            false
        };
        if let AstNode::FieldAccess { target, .. } = &e {
            if let AstNode::Ident { .. } = target.as_ref() {
                if first_token_is_dollar_ident
                    && !contains_call(&e)
                    && !self.starts_positional_arg()
                    && (self.at_eof()
                        || self.at(Token::Semi)
                        || self.at(Token::RBrace)
                        || self.has_newline_before_current())
                {
                    if self.at(Token::Semi) {
                        self.consume();
                    }
                    return AstNode::Call {
                        span: self.span(),
                        callee: Box::new(e),
                        args: vec![],
                    };
                }
            }
        }
        if self.at(Token::Semi) {
            self.consume();
        }
        e
    }

    fn expr(&mut self) -> AstNode {
        let mut e = self.coalesce();
        // Only consume `|>` when not inside a pipeline stage's lambda body
        while self.at(Token::Pipeline) && self.pipeline_depth == 0 {
            self.consume();
            e = self.pipeline_stage(e);
        }
        if self.at(Token::If) && !self.has_newline_before_current() {
            let span = self.span();
            self.consume(); // if
            let condition = self.expr();
            self.expect(Token::Else);
            let else_expr = self.expr();
            e = AstNode::If {
                span,
                condition: Box::new(condition),
                then_branch: vec![e],
                else_branch: Some(vec![else_expr]),
            };
        }
        e
    }

    fn coalesce(&mut self) -> AstNode {
        let mut e = self.or_expr();
        while self.at(Token::Coalesce) {
            let span = self.span();
            self.consume();
            let r = Box::new(self.coalesce());
            e = AstNode::BinaryOp {
                span,
                left: Box::new(e),
                op: BinaryOperator::Coalesce,
                right: r,
            };
        }
        e
    }

    fn or_expr(&mut self) -> AstNode {
        let mut e = self.and_expr();
        while self.at(Token::Or) || self.at(Token::OrOp) {
            let span = self.span();
            self.consume();
            let r = Box::new(self.and_expr());
            e = AstNode::BinaryOp {
                span,
                left: Box::new(e),
                op: BinaryOperator::Or,
                right: r,
            };
        }
        e
    }

    fn and_expr(&mut self) -> AstNode {
        let mut e = self.equality();
        while self.at(Token::And) || self.at(Token::AndOp) {
            let span = self.span();
            self.consume();
            let r = Box::new(self.equality());
            e = AstNode::BinaryOp {
                span,
                left: Box::new(e),
                op: BinaryOperator::And,
                right: r,
            };
        }
        e
    }

    fn equality(&mut self) -> AstNode {
        let mut e = self.bit_or();
        loop {
            let op = match self.current().map(|t| &t.token) {
                Some(Token::Eq) => BinaryOperator::Eq,
                Some(Token::NotEq) => BinaryOperator::NotEq,
                _ => break,
            };
            let span = self.span();
            self.consume();
            let r = Box::new(self.bit_or());
            e = AstNode::BinaryOp {
                span,
                left: Box::new(e),
                op,
                right: r,
            };
        }
        e
    }

    fn bit_or(&mut self) -> AstNode {
        let mut e = self.bit_xor();
        while self.at(Token::Pipe) {
            let span = self.span();
            self.consume();
            let r = Box::new(self.bit_xor());
            e = AstNode::BinaryOp {
                span,
                left: Box::new(e),
                op: BinaryOperator::BitOr,
                right: r,
            };
        }
        e
    }

    fn bit_xor(&mut self) -> AstNode {
        let mut e = self.bitwise_and();
        while self.at(Token::BitXor) {
            let span = self.span();
            self.consume();
            let r = Box::new(self.bitwise_and());
            e = AstNode::BinaryOp {
                span,
                left: Box::new(e),
                op: BinaryOperator::BitXor,
                right: r,
            };
        }
        e
    }

    fn bitwise_and(&mut self) -> AstNode {
        let mut e = self.comparison();
        loop {
            if !self.at(Token::BitAnd) {
                break;
            }
            let span = self.span();
            self.consume();
            let r = Box::new(self.comparison());
            e = AstNode::BinaryOp {
                span,
                left: Box::new(e),
                op: BinaryOperator::BitAnd,
                right: r,
            };
        }
        e
    }

    fn comparison(&mut self) -> AstNode {
        let mut e = self.range_expr();
        loop {
            let op = match self.current().map(|t| &t.token) {
                Some(Token::Lt) => BinaryOperator::Lt,
                Some(Token::Gt) => BinaryOperator::Gt,
                Some(Token::Le) => BinaryOperator::Le,
                Some(Token::Ge) => BinaryOperator::Ge,
                Some(Token::In) => BinaryOperator::In,
                Some(Token::Is) => {
                    let span = self.span();
                    self.consume();
                    // Check if the next token is a type name — type test
                    // Accepts IdentPlain (custom types) and primitive type keywords
                    let is_type_keyword = matches!(
                        self.current().map(|t| &t.token),
                        Some(
                            Token::Str
                                | Token::I8
                                | Token::I16
                                | Token::I32
                                | Token::I64
                                | Token::U8
                                | Token::U16
                                | Token::U32
                                | Token::U64
                                | Token::F32
                                | Token::F64
                                | Token::Bool
                                | Token::Any
                        )
                    );
                    if self.at(Token::IdentPlain) || is_type_keyword {
                        let type_name = self.parse_type();
                        e = AstNode::TypeTest {
                            span,
                            value: Box::new(e),
                            type_name,
                        };
                    } else if self.looks_like_expr_start() {
                        // Fallback: equality check
                        let r = Box::new(self.primary());
                        e = AstNode::BinaryOp {
                            span,
                            left: Box::new(e),
                            op: BinaryOperator::Eq,
                            right: r,
                        };
                    }
                    // If not a valid expr start (e.g., `}`), treat `is` as part of the
                    // left-hand side identifier and don't consume it as an operator.
                    continue;
                }
                Some(Token::As) => {
                    let span = self.span();
                    self.consume();
                    // Parse as type cast: `$x as i32`
                    let type_name = self.parse_type();
                    e = AstNode::TypeCast {
                        span,
                        value: Box::new(e),
                        type_name,
                    };
                    continue;
                }
                _ => break,
            };
            let span = self.span();
            self.consume();
            let r = Box::new(self.range_expr());
            e = AstNode::BinaryOp {
                span,
                left: Box::new(e),
                op,
                right: r,
            };
        }
        e
    }

    fn range_expr(&mut self) -> AstNode {
        let start = self.additive();
        if self.at(Token::Range) {
            let span = self.span();
            self.consume();
            let end = if self.at_eof() || !self.looks_like_expr_start() {
                None
            } else {
                Some(Box::new(self.additive()))
            };
            return AstNode::Range {
                span,
                start: Some(Box::new(start)),
                end,
            };
        }
        start
    }

    #[inline]
    fn looks_like_expr_start(&self) -> bool {
        matches!(
            self.current().map(|t| &t.token),
            Some(Token::Int)
                | Some(Token::Float)
                | Some(Token::IntHex)
                | Some(Token::IntBin)
                | Some(Token::IntOct)
                | Some(Token::Ident)
                | Some(Token::IdentPlain)
                | Some(Token::Str)
                | Some(Token::I8)
                | Some(Token::I16)
                | Some(Token::I32)
                | Some(Token::I64)
                | Some(Token::U8)
                | Some(Token::U16)
                | Some(Token::U32)
                | Some(Token::U64)
                | Some(Token::F32)
                | Some(Token::F64)
                | Some(Token::Sub)
                | Some(Token::Not)
                | Some(Token::Bang)
                | Some(Token::BitNot)
                | Some(Token::LParen)
                | Some(Token::LBracket)
                | Some(Token::Pipe)
        )
    }

    fn additive(&mut self) -> AstNode {
        let mut e = self.shift();
        loop {
            let op = match self.current().map(|t| &t.token) {
                Some(Token::Add) => BinaryOperator::Add,
                Some(Token::Sub) => BinaryOperator::Sub,
                _ => break,
            };
            let span = self.span();
            self.consume();
            let r = Box::new(self.shift());
            e = AstNode::BinaryOp {
                span,
                left: Box::new(e),
                op,
                right: r,
            };
        }
        e
    }

    fn shift(&mut self) -> AstNode {
        let mut e = self.multiplicative();
        loop {
            let op = match self.current().map(|t| &t.token) {
                Some(Token::Shl) => BinaryOperator::Shl,
                Some(Token::Shr) => BinaryOperator::Shr,
                _ => break,
            };
            let span = self.span();
            self.consume();
            let r = Box::new(self.multiplicative());
            e = AstNode::BinaryOp {
                span,
                left: Box::new(e),
                op,
                right: r,
            };
        }
        e
    }

    fn multiplicative(&mut self) -> AstNode {
        let mut e = self.power();
        loop {
            let op = match self.current().map(|t| &t.token) {
                Some(Token::Mul) => BinaryOperator::Mul,
                Some(Token::Div) => BinaryOperator::Div,
                Some(Token::Mod) => BinaryOperator::Mod,
                _ => break,
            };
            let span = self.span();
            self.consume();
            let r = Box::new(self.power());
            e = AstNode::BinaryOp {
                span,
                left: Box::new(e),
                op,
                right: r,
            };
        }
        e
    }

    fn power(&mut self) -> AstNode {
        let e = self.unary();
        if self.at(Token::Pow) {
            let span = self.span();
            self.consume();
            let r = Box::new(self.power());
            AstNode::BinaryOp {
                span,
                left: Box::new(e),
                op: BinaryOperator::Pow,
                right: r,
            }
        } else {
            e
        }
    }

    fn unary(&mut self) -> AstNode {
        let span = self.span();
        if self.at(Token::Sub) {
            self.consume();
            return AstNode::UnaryOp {
                span,
                op: UnaryOperator::Neg,
                operand: Box::new(self.unary()),
            };
        }
        if self.at(Token::Not) {
            self.consume();
            return AstNode::UnaryOp {
                span,
                op: UnaryOperator::Not,
                operand: Box::new(self.unary()),
            };
        }
        if self.at(Token::BitNot) {
            let span = self.span();
            self.consume();
            return AstNode::UnaryOp {
                span,
                op: UnaryOperator::BitNot,
                operand: Box::new(self.unary()),
            };
        }
        if self.at(Token::Bang) {
            self.consume();
            return self.unary();
        }
        self.postfix()
    }

    /// Lookahead: does [ look like an index ($arr[0]) or an array literal ([1, 2, 3])?
    /// An index has a single expression followed by ]. An array has commas.
    fn lookahead_index(&self) -> bool {
        // self.pos points at LBracket. Scan from pos+1.
        let mut i = self.pos + 1;
        let mut depth = 1;
        while i < self.tokens.len() && depth > 0 {
            match self.tokens[i].token {
                Token::LBracket | Token::LParen | Token::LBrace => depth += 1,
                Token::RBracket | Token::RParen | Token::RBrace => depth -= 1,
                Token::Comma if depth == 1 => return false, // comma at top level = array literal
                _ => {}
            }
            if depth > 0 {
                i += 1;
            }
        }
        true // no comma found = index expression
    }

    /// Try to parse lambda parameters: a list of $-identifiers separated by commas, ending with RParen.
    /// Returns Some(params) if successful and consumes the RParen, otherwise None without consuming tokens.
    fn try_parse_lambda_params(&mut self) -> Option<Vec<String>> {
        // self.pos points to the first token after LParen
        let mut params = Vec::new();
        let mut pos = self.pos;

        if pos >= self.tokens.len() {
            return None;
        }

        // Parse first param
        match &self.tokens[pos].token {
            Token::Ident => {
                let name = self.tokens[pos].text.trim_start_matches('$').to_string();
                params.push(name);
                pos += 1;
            }
            Token::RParen => {
                // Empty params: () => expr
                self.pos = pos + 1; // consume RParen
                return Some(params);
            }
            _ => return None,
        }

        // Parse remaining params
        loop {
            if pos >= self.tokens.len() {
                return None;
            }
            match &self.tokens[pos].token {
                Token::Comma | Token::Semi => {
                    pos += 1;
                    if pos >= self.tokens.len() {
                        return None;
                    }
                    // Check for next param
                    match &self.tokens[pos].token {
                        Token::Ident => {
                            let name = self.tokens[pos].text.trim_start_matches('$').to_string();
                            params.push(name);
                            pos += 1;
                        }
                        Token::RParen => {
                            // Trailing comma: ($x,) => expr
                            self.pos = pos + 1;
                            return Some(params);
                        }
                        _ => return None,
                    }
                }
                Token::RParen => {
                    self.pos = pos + 1; // consume RParen
                    return Some(params);
                }
                _ => return None,
            }
        }
    }

    /// Parse pipe-style lambda: |$x, $y| expr — params must use $ prefix
    fn pipe_lambda(&mut self) -> AstNode {
        let span = self.span();
        self.consume(); // consume first |
        let mut params = Vec::new();
        while !self.at(Token::Pipe) && !self.at_eof() {
            // Pipe lambda params must use $ prefix: |$x| $x * 2
            let t = self.consume();
            if !matches!(&t.token, Token::Ident) {
                panic!(
                    "XCL {}:{}: pipe lambda parameter must use $ prefix, got '{}' (use ${} instead)",
                    t.span.line, t.span.col, t.text, t.text
                );
            }
            let name = t.text.trim_start_matches('$').to_string();
            params.push(name);
            if self.at(Token::Comma) || self.at(Token::Semi) {
                self.consume();
            }
        }
        self.expect(Token::Pipe); // consume closing |
        let body = Box::new(self.expr());
        AstNode::Lambda { span, params, body }
    }

    fn postfix(&mut self) -> AstNode {
        let mut e = self.primary();
        // Track whether this expression starts with a domain function (IdentPlain)
        // Domain functions like `collections.map` should not have [ ] index operations
        // because [ ] after them is a call arg (array literal), not an index.
        let starts_with_ident_plain = {
            // Walk backwards from current position to find the first token of this expression
            if self.pos > 0 {
                let mut pos = self.pos - 1;
                while pos < self.tokens.len()
                    && matches!(
                        self.tokens.get(pos).map(|t| &t.token),
                        Some(Token::Dot | Token::OptionalDot | Token::Ident | Token::IdentPlain)
                    )
                    && pos > 0
                {
                    pos -= 1;
                }
                matches!(
                    self.tokens.get(pos).map(|t| &t.token),
                    Some(Token::IdentPlain)
                )
            } else {
                false
            }
        };

        loop {
            match self.current().map(|t| &t.token) {
                Some(Token::Dot) | Some(Token::OptionalDot) => {
                    self.consume();
                    let field = self.consume().text.clone();
                    e = AstNode::FieldAccess {
                        span: self.span(),
                        target: Box::new(e),
                        field,
                    };
                }
                Some(Token::LBracket) => {
                    // Lookahead: if [ is followed by ] or by expr,], it's an index.
                    // If [ is followed by expr, expr, ... ], it's an array literal (call arg).
                    // For domain functions (IdentPlain), [ ] is always a call arg.
                    if starts_with_ident_plain || !self.lookahead_index() {
                        // Skip — let call detection handle it as a call arg
                        break;
                    } else {
                        self.consume();
                        let idx = self.expr();
                        self.expect(Token::RBracket);
                        e = AstNode::Index {
                            span: self.span(),
                            target: Box::new(e),
                            index: Box::new(idx),
                        };
                    }
                }
                _ => break,
            }
        }

        // Space-separated call after a bare dotted path.
        // Only apply when the previous token was an IdentPlain (not $-ident).
        // $-ident calls are handled by expr_stmt at the statement level.
        let prev_is_ident =
            self.pos > 0 && matches!(self.tokens[self.pos - 1].token, Token::IdentPlain);
        // `f (a) b c` is a three-argument call. The first argument is
        // parenthesized, so the previous token is `)`, not an identifier; a call
        // produced by parenthesized arguments must still accept the remaining
        // space-separated ones. Without this, `hanoi ($n - 1) $from $via $to`
        // compiles as `hanoi($n - 1)` followed by a discarded call.
        let call_from_parens = matches!(e, AstNode::Call { .. });

        if (prev_is_ident || call_from_parens)
            && matches!(
                e,
                AstNode::Ident { .. } | AstNode::FieldAccess { .. } | AstNode::Call { .. }
            )
            && self.starts_positional_arg()
            && !self.has_newline_before_current()
        {
            // Skip $f.method $x when $x is also a field access ($x.field)
            // because $x.field is a separate arg, not a call to $f.method
            let skip = matches!(e, AstNode::FieldAccess { .. })
                && self.at(Token::Ident)
                && matches!(
                    self.tokens.get(self.pos + 1).map(|t| &t.token),
                    Some(Token::Dot) | Some(Token::LBracket)
                );
            // Skip { after FieldAccess on a $-variable when it's a block-lambda (not a dict).
            // This prevents `if $x.field { }` from being misparsed as a call
            // `if($x.field, { })`. Dict literals and domain functions (env.override, etc.)
            // are allowed because their FieldAccess target starts with a plain identifier.
            // Check the token stream: if the expression started with Token::Ident ($-var),
            // skip the brace. If it started with Token::IdentPlain (domain function), allow it.
            let skip_brace = if let AstNode::FieldAccess { target, .. } = &e {
                if let AstNode::Ident { .. } = target.as_ref() {
                    // Find the token that produced this ident - check if it was $-prefixed
                    // by looking at the token just before the dot in the token stream
                    let dot_pos = self.tokens.iter().rposition(|t| {
                        matches!(t.token, Token::Dot | Token::OptionalDot)
                            && t.byte_offset
                                < self
                                    .tokens
                                    .get(self.pos - 1)
                                    .map(|t| t.byte_offset)
                                    .unwrap_or(0)
                    });
                    if let Some(dp) = dot_pos {
                        let before_dot = dp.saturating_sub(1);
                        let is_dollar_var = matches!(
                            self.tokens.get(before_dot).map(|t| &t.token),
                            Some(Token::Ident)
                        );
                        is_dollar_var && self.at(Token::LBrace) && !self.lookahead_dict_literal()
                    } else {
                        false
                    }
                } else {
                    false
                }
            } else {
                false
            };
            if skip || skip_brace {
                // Do nothing — leave the token for the caller
            } else {
                // If e is already a Call (from parenthesized args), merge additional args
                let mut args: Vec<CallArg> = if let AstNode::Call { args, .. } = &e {
                    args.clone()
                } else {
                    Vec::new()
                };
                let callee: Box<AstNode> = if let AstNode::Call { callee, .. } = e {
                    callee
                } else {
                    Box::new(e)
                };
                while self.starts_positional_arg() && !self.has_newline_before_current() {
                    args.push(self.call_arg());
                }
                while self.at(Token::Comma) {
                    self.consume();
                    if self.starts_positional_arg() && !self.has_newline_before_current() {
                        args.push(self.call_arg());
                    }
                }
                e = AstNode::Call {
                    span: self.span(),
                    callee,
                    args,
                };
            }
        }

        e
    }

    fn call_arg(&mut self) -> CallArg {
        if self.at(Token::IdentPlain) {
            let next = self.pos + 1;
            if matches!(self.tokens.get(next).map(|t| &t.token), Some(Token::Assign)) {
                let name = self.consume().text.clone();
                self.consume();
                // Named args parse full expressions (they're unambiguous)
                let value = self.expr();
                return CallArg {
                    value,
                    name: Some(name),
                };
            }
        }
        // Positional args parse at unary level so binary operators (>, <, ==, +, -)
        // are handled by the precedence climbing above postfix.
        // This means `math.sqrt 16 > 3` parses as `(math.sqrt 16) > 3`, not `math.sqrt (16 > 3)`.
        // Use parentheses for multi-operator args: `math.add (1 + 2)`.
        CallArg {
            value: self.unary(),
            name: None,
        }
    }

    fn primary(&mut self) -> AstNode {
        let t = self.consume();
        let span = t.span.clone();
        match t.token {
            Token::Int => AstNode::Int {
                span,
                value: t.text.trim().parse().unwrap_or(0),
            },
            Token::Float => AstNode::Float {
                span,
                value: t.text.trim().parse().unwrap_or(0.0),
            },
            Token::IntHex => {
                let hex = t.text.trim_start_matches("0x").trim_start_matches("0X");
                AstNode::Int {
                    span,
                    value: i64::from_str_radix(hex, 16).unwrap_or(0),
                }
            }
            Token::IntBin => {
                let bin = t.text.trim_start_matches("0b").trim_start_matches("0B");
                AstNode::Int {
                    span,
                    value: i64::from_str_radix(bin, 2).unwrap_or(0),
                }
            }
            Token::IntOct => {
                let oct = t.text.trim_start_matches("0o");
                AstNode::Int {
                    span,
                    value: i64::from_str_radix(oct, 8).unwrap_or(0),
                }
            }
            Token::String | Token::RawString | Token::MultiLineString => AstNode::Str {
                span,
                value: extract_string(&t.text),
            },
            Token::True => AstNode::Bool { span, value: true },
            Token::False => AstNode::Bool { span, value: false },
            Token::None_ => AstNode::Nil { span },

            Token::Ident => {
                let name = t.text.trim_start_matches('$').to_string();
                AstNode::Ident { span, name }
            }

            Token::SpecialVar => {
                let (kind, index) = match t.text.as_str() {
                    "$0" => (SpecialVarKind::ScriptName, 0),
                    "$#" => (SpecialVarKind::ArgCount, 0),
                    "$@" => (SpecialVarKind::ArgsArray, 0),
                    "$*" => (SpecialVarKind::ArgsJoined, 0),
                    text => {
                        let index = text[1..].parse::<u32>().unwrap_or_else(|_| {
                            panic!(
                                "XCL {}:{}: invalid positional argument `{}`",
                                t.span.file, t.span.line, text
                            )
                        });
                        if index == 0 {
                            (SpecialVarKind::ScriptName, 0)
                        } else {
                            (SpecialVarKind::Positional, index)
                        }
                    }
                };
                AstNode::SpecialVar { span, kind, index }
            }

            Token::UnsupportedSpecialVar => panic!(
                "XCL {}:{}: shell special variable `{}` is not supported in XCL",
                t.span.file, t.span.line, t.text
            ),

            Token::IdentPlain => {
                let name = t.text.clone();
                // Check if this looks like a function definition: `name( ... ) {` or `name( ... ) ->`
                // If so, don't parse as a call — let the caller handle it
                if self.at(Token::LParen) && self.lookahead_fn_def_from_paren() {
                    return AstNode::Ident { span, name };
                }
                // Standard function call: `name(args)` — parse with parentheses
                if self.at(Token::LParen) {
                    self.consume(); // consume (
                    let mut args = Vec::new();
                    while !self.at(Token::RParen) && !self.at_eof() {
                        if self.at(Token::Comma) {
                            self.consume();
                            continue;
                        }
                        // Named arg: `name = value`
                        if self.at(Token::IdentPlain) {
                            let next = self.pos + 1;
                            if matches!(
                                self.tokens.get(next).map(|t| &t.token),
                                Some(Token::Assign)
                            ) {
                                let aname = self.consume().text.clone();
                                self.consume(); // =
                                let aval = self.expr();
                                args.push(CallArg {
                                    value: aval,
                                    name: Some(aname),
                                });
                                continue;
                            }
                        }
                        let aval = self.expr();
                        args.push(CallArg {
                            value: aval,
                            name: None,
                        });
                    }
                    self.expect(Token::RParen);
                    return AstNode::Call {
                        span: span.clone(),
                        callee: Box::new(AstNode::Ident { span, name }),
                        args,
                    };
                }
                // Space-separated domain-style call: `domain func arg`
                let mut args = Vec::new();
                while self.looks_like_arg() {
                    args.push(self.call_arg());
                }
                while self.at(Token::Comma) {
                    self.consume();
                    if self.looks_like_arg() {
                        args.push(self.call_arg());
                    }
                }
                if args.is_empty() {
                    AstNode::Ident { span, name }
                } else {
                    AstNode::Call {
                        span: span.clone(),
                        callee: Box::new(AstNode::Ident { span, name }),
                        args,
                    }
                }
            }

            Token::LBracket => {
                let mut elements = Vec::new();
                while !self.at(Token::RBracket) && !self.at_eof() {
                    elements.push(self.expr());
                    if self.at(Token::Comma) || self.at(Token::Semi) {
                        self.consume();
                    }
                }
                self.expect(Token::RBracket);
                AstNode::ArrayLit { span, elements }
            }

            Token::LBrace => {
                // Lookahead: if the first meaningful token inside { is followed by `:`, it's a dict literal.
                // Otherwise, it's a block-lambda (zero-param closure).
                if self.lookahead_dict_literal() {
                    let mut entries = Vec::new();
                    while !self.at(Token::RBrace) && !self.at_eof() {
                        if self.at(Token::Semi) || self.at(Token::Comma) {
                            self.consume();
                            continue;
                        }
                        let key = self.consume().text.clone();
                        if self.at(Token::Colon) {
                            self.consume();
                            let value = self.expr();
                            entries.push((key, value));
                        } else {
                            entries.push((
                                key.clone(),
                                AstNode::Ident {
                                    span: span.clone(),
                                    name: key,
                                },
                            ));
                        }
                    }
                    self.expect(Token::RBrace);
                    AstNode::DictLit { span, entries }
                } else {
                    // Block-lambda: { stmt1; stmt2; ... }
                    let mut statements = Vec::new();
                    while !self.at(Token::RBrace) && !self.at_eof() {
                        if self.at(Token::Semi) {
                            self.consume();
                            continue;
                        }
                        statements.push(self.statement());
                    }
                    self.expect(Token::RBrace);
                    AstNode::Lambda {
                        span: span.clone(),
                        params: vec![],
                        body: Box::new(AstNode::Block { span, statements }),
                    }
                }
            }

            Token::LParen => {
                // Check for arrow lambda: ($x, $y) => expr
                // First, try to parse params: a list of $-identifiers separated by commas
                let save_pos = self.pos;
                let params = self.try_parse_lambda_params();
                if let Some(params) = params {
                    // Successfully parsed params and consumed RParen
                    // Now expect =>
                    if self.at(Token::Arrow) {
                        self.consume(); // consume =>
                        let body = Box::new(self.expr());
                        return AstNode::Lambda {
                            span: span.clone(),
                            params,
                            body,
                        };
                    } else {
                        // Not a lambda, rewind and parse as regular parenthesized expr
                        self.pos = save_pos;
                        let e = self.expr();
                        self.expect(Token::RParen);
                        return e;
                    }
                } else {
                    // Not lambda params, parse as regular parenthesized expr
                    self.pos = save_pos;
                    let e = self.expr();
                    self.expect(Token::RParen);
                    return e;
                }
            }

            Token::Pipe => {
                // Pipe-style lambda: |x, y| expr
                // Token already consumed, self.pos is at the first param
                let saved_pos = self.pos - 1; // back to the Pipe token
                // Reconstruct the parser state to call pipe_lambda
                self.pos = saved_pos;
                return self.pipe_lambda();
            }

            Token::If => {
                // `if` as an expression: $x = if cond { a } else { b }
                // Token already consumed, self.pos is past the If token
                self.pos -= 1; // back to the If token
                return self.if_expr();
            }

            Token::RArrow => {
                // Bare -> in expression context — likely a lambda without params
                panic!(
                    "XCL {}:{}: unexpected '->' in expression. Did you mean '(x) -> expr' for a lambda?",
                    t.span.file, t.span.line
                )
            }

            _ => panic!(
                "XCL {}:{}: unexpected token {:?} ({})",
                t.span.file, t.span.line, t.token, t.text
            ),
        }
    }

    #[inline]
    fn looks_like_arg(&self) -> bool {
        // If there's a newline before the current token, it's not an arg
        if self.has_newline_before_current() {
            return false;
        }
        match self.current().map(|t| &t.token) {
            None => false,
            Some(Token::Ident) => {
                // $-prefixed identifiers are args if:
                // 1. Followed by = (named arg: $x = value)
                // 2. Followed by . (field access: $x.field)
                // 3. Followed by [ (index access: $x[0])
                // NOT if followed by another $-ident (that's a call: $f $x)
                let next = self.tokens.get(self.pos + 1).map(|t| &t.token);
                matches!(
                    next,
                    Some(Token::Assign)
                        | Some(Token::CoalesceAssign)
                        | Some(Token::AddAssign)
                        | Some(Token::SubAssign)
                        | Some(Token::MulAssign)
                        | Some(Token::DivAssign)
                        | Some(Token::BitOrAssign)
                        | Some(Token::BitXorAssign)
                        | Some(Token::PowAssign)
                        | Some(Token::Dot)
                        | Some(Token::LBracket)
                )
            }
            Some(Token::LBrace) => {
                // Allow both block-lambda { stmts } and dict literals { key: val } as args
                true
            }
            Some(t) => matches!(
                t,
                Token::Bool
                    | Token::Any
                    | Token::Str
                    | Token::I8
                    | Token::I16
                    | Token::I32
                    | Token::I64
                    | Token::U8
                    | Token::U16
                    | Token::U32
                    | Token::U64
                    | Token::F32
                    | Token::F64
                    | Token::Int
                    | Token::Float
                    | Token::IntHex
                    | Token::IntBin
                    | Token::IntOct
                    | Token::String
                    | Token::RawString
                    | Token::MultiLineString
                    | Token::True
                    | Token::False
                    | Token::None_
                    | Token::LBracket
                    | Token::LParen
                    | Token::BitNot
                    | Token::SpecialVar
            ),
        }
    }

    /// Check if there's a newline between the previous token and the current token.
    #[inline]
    fn has_newline_before_current(&self) -> bool {
        if self.pos == 0 {
            return false;
        }
        let prev = &self.tokens[self.pos - 1];
        let cur = match self.current() {
            Some(t) => t,
            None => return true,
        };
        let gap_start = prev.byte_offset + prev.text.len();
        let gap_end = cur.byte_offset;
        if gap_end > gap_start {
            let gap = &self.source[gap_start..gap_end.min(self.source.len())];
            gap.contains('\n')
        } else {
            false
        }
    }

    /// Like `looks_like_arg`, but excludes `{` after control-flow keywords
    /// (e.g. `if $x { ... }`). After a dotted path or $-ident call, `{` is a block-lambda arg.
    #[inline]
    fn starts_positional_arg(&self) -> bool {
        match self.current().map(|t| &t.token) {
            None => false,
            Some(Token::Ident) => !matches!(
                self.tokens.get(self.pos + 1).map(|t| &t.token),
                Some(Token::Assign)
                    | Some(Token::Semi)
                    | Some(Token::Colon)
                    | Some(Token::CoalesceAssign)
                    | Some(Token::AddAssign)
                    | Some(Token::SubAssign)
                    | Some(Token::MulAssign)
                    | Some(Token::DivAssign)
                    | Some(Token::BitOrAssign)
                    | Some(Token::BitXorAssign)
                    | Some(Token::PowAssign)
            ),
            Some(Token::IdentPlain) => {
                // IdentPlain can be a positional arg (e.g., `allow file.read "/data/"`)
                // but NOT if it looks like a type definition (`Name =`), impl (`Name is`),
                // or bare function definition (`Name(`).
                let next = self.tokens.get(self.pos + 1).map(|t| &t.token);
                // Skip if it's an assignment: `$x = value` or `Name = {`
                if matches!(next, Some(Token::Assign) | Some(Token::Colon)) {
                    return false;
                }
                // Skip if it's `Name is Trait`
                if matches!(next, Some(Token::Is)) {
                    return false;
                }
                // Skip if it's `Name(` (bare function definition at statement level)
                // But allow it in expression context (like `allow file.read`)
                // The key: if followed by `(` and then `{` or `->`, it's a fn def
                if matches!(next, Some(Token::LParen)) {
                    // Check if this looks like a function definition
                    if self.lookahead_fn_def_at(self.pos) {
                        return false;
                    }
                }
                true
            }
            Some(Token::LBrace) => {
                // Allow both block-lambda { stmts } and dict literals { key: val } as args
                true
            }
            Some(t) => matches!(
                t,
                Token::Bool
                    | Token::Any
                    | Token::Str
                    | Token::I8
                    | Token::I16
                    | Token::I32
                    | Token::I64
                    | Token::U8
                    | Token::U16
                    | Token::U32
                    | Token::U64
                    | Token::F32
                    | Token::F64
                    | Token::Int
                    | Token::Float
                    | Token::IntHex
                    | Token::IntBin
                    | Token::IntOct
                    | Token::String
                    | Token::RawString
                    | Token::MultiLineString
                    | Token::True
                    | Token::False
                    | Token::None_
                    | Token::LBracket
                    | Token::LParen
                    | Token::BitNot
                    | Token::SpecialVar
            ),
        }
    }

    /// Check if position looks like a bare function definition: `Name( ... ) {` or `Name( ... ) ->`
    fn lookahead_fn_def_at(&self, pos: usize) -> bool {
        if !matches!(
            self.tokens.get(pos).map(|t| &t.token),
            Some(Token::IdentPlain)
        ) {
            return false;
        }
        if !matches!(
            self.tokens.get(pos + 1).map(|t| &t.token),
            Some(Token::LParen)
        ) {
            return false;
        }
        // Find matching closing paren
        let mut depth = 1;
        let mut i = pos + 2;
        while i < self.tokens.len() && depth > 0 {
            match self.tokens[i].token {
                Token::LParen => depth += 1,
                Token::RParen => depth -= 1,
                _ => {}
            }
            if depth > 0 {
                i += 1;
            }
        }
        if depth != 0 {
            return false;
        }
        // After closing paren, expect { or ->
        matches!(
            self.tokens.get(i).map(|t| &t.token),
            Some(Token::LBrace) | Some(Token::RArrow)
        )
    }

    fn pipeline_stage(&mut self, input: AstNode) -> AstNode {
        let span = self.span();
        // Parse the pipeline stage name, which can be a dotted path like `collections.filter`
        let mut name = self.consume().text.clone();
        while self.at(Token::Dot) {
            self.consume(); // consume Dot
            let field = self.consume().text.clone();
            name = format!("{}.{}", name, field);
        }
        // Increment pipeline depth so lambda bodies don't consume the next `|>` stage.
        self.pipeline_depth += 1;
        let arg = if self.looks_like_arg() {
            Some(Box::new(self.expr()))
        } else {
            None
        };
        self.pipeline_depth -= 1;
        AstNode::Pipeline {
            span,
            input: Box::new(input),
            stages: vec![PipelineStage { name, arg }],
        }
    }

    /// Check if current position (at LParen) looks like a function definition.
    /// Used by primary() to avoid parsing `name()` as a call when it's a fn def.
    fn lookahead_fn_def_from_paren(&self) -> bool {
        // self.pos points at LParen. Scan for matching RParen.
        let mut depth = 1;
        let mut i = self.pos + 1;
        while i < self.tokens.len() && depth > 0 {
            match self.tokens[i].token {
                Token::LParen => depth += 1,
                Token::RParen => depth -= 1,
                _ => {}
            }
            if depth > 0 {
                i += 1;
            }
        }
        if depth != 0 {
            return false;
        }
        // After closing paren, expect { or ->
        matches!(
            self.tokens.get(i).map(|t| &t.token),
            Some(Token::LBrace) | Some(Token::RArrow)
        )
    }
}

/// Parses a stream of lexer tokens into an Abstract Syntax Tree (AST).
///
/// Converts tokenized input into a sequence of top-level [`AstNode`] statements
/// representing functions, variable definitions, and executable expressions.
///
/// # Arguments
///
/// * `tokens` - The token stream produced by [`lexer::lex`](crate::lexer::lex).
/// * `source` - The original source code string, used for extracting identifier texts and error snippets.
///
/// # Returns
///
/// A vector of parsed [`AstNode`] objects ready for bytecode compilation.
///
/// # Panics
///
/// Panics if a syntax error is encountered (such as unexpected tokens or missing delimiters),
/// reporting the offending file, line, column, expected token, and actual token.
///
/// # Examples
///
/// ```
/// use xcl_vm::compiler::lexer::lex;
/// use xcl_vm::compiler::parser::parse;
///
/// let tokens = lex("1 + 2 * 3", "<eval>");
/// let ast = parse(&tokens, "1 + 2 * 3");
/// assert_eq!(ast.len(), 1);
/// ```
pub fn parse(tokens: &[TokenWithText], source: &str) -> Vec<AstNode> {
    Parser::new(tokens, source).program()
}
